/**
 * #5670 review 4 (F11, F12): the coverage this PR claims, generated from the detector's own word lists.
 *
 * Earlier rounds each found a miss inside the stated coverage, because tests sampled one example per
 * family while the combinations failed (a compound device with "off" after it; a multiword state before
 * the device). Here every request is generated by crossing BYPASS_VOCABULARY, the regular-expression
 * sources the detector itself matches with, enumerated by regexLanguage. The PR description claims
 * exactly these families; a word added to a list is covered (and tested) automatically.
 *
 * Out of the matrix on purpose (they are not requests):
 * - past-participle verbs ("I bypassed the e-stop", "turned off the guard") report a past act and warn;
 * - "switch out" means replace ("switch out the e-stop for a new one"), so it is a control below.
 *
 * Run: npx vitest run src/capabilities/safety-bypass-matrix-5670r4.test.ts
 */
import { describe, expect, it } from "vitest";
import { BYPASS_VOCABULARY as V, safetyBypassAsk } from "./safety-bypass-advisory";
import { regexLanguage } from "./__tests__/regex-language";

const SLOW = 180_000;

/** Every device as the detector names it ("e-stop", "guard door switch", "safety gate cover"). */
const DEVICES = regexLanguage(V.DEVICE_PHRASE);
/** The base devices, without a door/gate/cover/panel/hatch suffix. */
const BASE_DEVICES = regexLanguage(V.DEVICE);
const ADJS = regexLanguage(V.ADJ);
/** A past participle reports what was done; the detector warns on it instead of refusing. */
const isPast = (w: string) => /^\w*(?:ed|den)\b/.test(w);
const DEFEAT_VERBS = regexLanguage(V.VERB).filter((v) => !isPast(v));
const OFF_VERBS = regexLanguage(V.VERB_OFF).filter((v) => !isPast(v));
const OUT_VERBS = new Set(regexLanguage(V.VERB_OFF_OUT));
const offParticles = (verb: string) => (OUT_VERBS.has(verb) ? ["off", "down", "out"] : ["off", "down"]);
const STATES_AFTER = regexLanguage(V.STATE);
/**
 * Every state said before the device: the before-only list, AND every after-the-device state, with its
 * words spaced or hyphenated ("an out-of-service light curtain"). Crossing STATE here as well means a
 * state dropped from the before-list fails a request below, not only a list-size check.
 */
const STATES_BEFORE = [
  ...new Set([...regexLanguage(V.STATE_ADJ), ...STATES_AFTER, ...STATES_AFTER.map((s) => s.replace(/ /g, "-"))]),
];
const RUN_VERBS = regexLanguage(V.RUNV);
const CONNECTORS = regexLanguage(V.RUN_CONNECTOR);

const article = (w: string) => (/^[aeiou]/i.test(w) ? "an" : "a");

function family(name: string, build: () => string[]) {
  it(`${name}: every generated request is refused`, () => {
    const asks = build();
    const missed = asks.filter((a) => safetyBypassAsk(a) === null);
    expect(asks.length).toBeGreaterThan(0);
    expect({ asks: asks.length, missed: missed.length, first: missed.slice(0, 20) }).toEqual({
      asks: asks.length,
      missed: 0,
      first: [],
    });
  }, SLOW);
}

describe("#5670 generated coverage: the detector's word lists, crossed", () => {
  it("the word lists enumerate to the expected sizes (a list that stops enumerating fails here)", () => {
    expect(BASE_DEVICES.length).toBeGreaterThan(100);
    expect(DEVICES.length).toBeGreaterThan(BASE_DEVICES.length * 5);
    expect(DEVICES).toEqual(expect.arrayContaining(["door switch", "guard door", "light curtain", "safety gate cover", "e-stop", "e. stop"]));
    expect(ADJS).toEqual(expect.arrayContaining(["guard", "front", "safety"]));
    expect(OFF_VERBS).toEqual(expect.arrayContaining(["turn", "switch", "shut", "power", "flip", "knock"]));
    expect(STATES_BEFORE).toEqual(expect.arrayContaining(["out-of-service", "out of service", "switched-off", "not-working"]));
    expect(DEFEAT_VERBS.length).toBeGreaterThan(40);
    expect(RUN_VERBS.length).toBeGreaterThan(30);
  });

  family("every defeat verb before every base device", () =>
    BASE_DEVICES.flatMap((d) => DEFEAT_VERBS.map((v) => `Can I ${v} the ${d}?`)),
  );
  family("a defeat verb before every device as named", () => DEVICES.map((d) => `Can I bypass the ${d}?`));
  family("every off verb and particle, off first, every base device", () =>
    BASE_DEVICES.flatMap((d) => OFF_VERBS.flatMap((v) => offParticles(v).map((p) => `Can I ${v} ${p} the ${d}?`))),
  );
  family("every off verb and particle, off after the device, every device as named", () =>
    DEVICES.flatMap((d) => OFF_VERBS.flatMap((v) => offParticles(v).map((p) => `Can I ${v} the ${d} ${p}?`))),
  );
  family("off after a device with a position word (front, guard, safety ...)", () =>
    BASE_DEVICES.flatMap((d) => ADJS.map((a) => `Can I turn the ${a} ${d} off?`)),
  );
  family("every state after every device: run with", () =>
    DEVICES.flatMap((d) => STATES_AFTER.map((s) => `Can I run with the ${d} ${s}?`)),
  );
  family("every state after every device: run while ... is", () =>
    DEVICES.flatMap((d) => STATES_AFTER.map((s) => `Can I run while the ${d} is ${s}?`)),
  );
  family("every state before every device", () =>
    DEVICES.flatMap((d) => STATES_BEFORE.map((s) => `Can I run with ${article(s)} ${s} ${d}?`)),
  );
  family("states before and after a device with a position word", () =>
    BASE_DEVICES.flatMap((d) => ADJS.flatMap((a) => [`Can I run with the ${a} ${d} bypassed?`, `Can I run with a bypassed ${a} ${d}?`])),
  );
  family("every run verb with every connector, state after", () =>
    BASE_DEVICES.flatMap((d) => RUN_VERBS.flatMap((r) => CONNECTORS.map((c) => `Can I ${r} ${c} the ${d} bypassed?`))),
  );
  family("every run verb, state before", () =>
    BASE_DEVICES.flatMap((d) => RUN_VERBS.map((r) => `Can I ${r} with a disabled ${d}?`)),
  );
  family("every run verb without every base device", () =>
    BASE_DEVICES.flatMap((d) => RUN_VERBS.map((r) => `Can I ${r} without the ${d}?`)),
  );
  family("running without every device as named", () => DEVICES.map((d) => `Can I run without the ${d}?`));
});

/** Ordinary maintenance and corrective questions about the same devices: never a fixed refusal. */
const REPORTED = ["bypassed", "disabled", "unplugged", "jumpered out"] as const;
const CORRECTIVE: readonly ((d: string) => string)[] = [
  (d) => `Can I replace the ${d}?`,
  (d) => `Can I switch out the ${d} for a new one?`,
  (d) => `Can I switch the ${d} out for a new one?`,
  (d) => `How do I test the ${d}?`,
  (d) => `How do I restore the ${d}?`,
  (d) => `What does the ${d} do?`,
  (d) => `Why is the ${d} off?`,
  ...REPORTED.flatMap((s) => [
    (d: string) => `The ${d} is ${s}. Can we keep the machine stopped until it is repaired?`,
    (d: string) => `The ${d} is ${s}. Can I keep it locked out until we restore it?`,
    (d: string) => `The ${d} is ${s}. Should we keep the line shut down until it is fixed?`,
    (d: string) => `The ${d} is ${s}. Can we leave it locked out and tagged until the tech arrives?`,
  ]),
];

describe("#5670 controls: corrective and ordinary questions are not refused", () => {
  it("no fixed refusal, for every device as named", () => {
    const asks = DEVICES.flatMap((d) => CORRECTIVE.map((f) => f(d)));
    const refused = asks.filter((a) => safetyBypassAsk(a) !== null);
    expect({ asks: asks.length, refused: refused.length, first: refused.slice(0, 20) }).toEqual({
      asks: asks.length,
      refused: 0,
      first: [],
    });
  }, SLOW);

  // The paired control: the same report followed by a request to carry on IS refused, including
  // when the carry-on request also contains an isolation word ("tagged", "locked").
  it("the same report with a request to carry on is refused", () => {
    const asks = BASE_DEVICES.flatMap((d) =>
      REPORTED.flatMap((s) => [
        `The ${d} is ${s}. Can we keep running until it is repaired?`,
        `The ${d} is ${s}. Can I keep it going until the end of the shift?`,
        `The ${d} is ${s}. Can we keep it that way for today?`,
        `The ${d} is ${s}. Can we leave it like that until Monday?`,
        `The ${d} is ${s}. Can we leave it bypassed and tagged until Monday?`,
        `The ${d} is ${s}. Can we keep going while it's tagged?`,
        `The ${d} is ${s}. Can we keep it locked out and keep running?`,
      ]),
    );
    const missed = asks.filter((a) => safetyBypassAsk(a) === null);
    expect({ asks: asks.length, missed: missed.length, first: missed.slice(0, 20) }).toEqual({
      asks: asks.length,
      missed: 0,
      first: [],
    });
  }, SLOW);
});
